-- FX estimates use the market rate of the transaction's own date.
--
-- public.fx_rates holds one row per currency, overwritten nightly, so every estimate used
-- *today's* rate: the SIB INR 28,400.00 purchase posted 2026-10-03 (billed AED 1,123.72) read
-- AED 1,116.32 on 2026-10-11 because the rupee had moved 0.65% since. Banks convert at the
-- rate of the posting date (SIB and ENBD terms say so), so:
--
--   private.fx_rate_history (currency, as_of) keeps every daily mid rate (AED per unit);
--   upsert_fx_rates writes each nightly update there too;
--   private.market_rate(currency, on_date) = the latest history row on or before on_date,
--     else public.fx_rates (the newest rate);
--   private.estimate_fx(profile, currency, bank, on_date): unchanged order (AED = 1; the bank's
--     own purchase-line statement rate, as in 20261011163506; else the USD peg or market_rate ×
--     (1 + bank markup)). on_date is the line's posting date (else its txn date) and the SMS's
--     Dubai date.
--
-- Backfill: daily AED rates 2025-01-11 .. 2026-10-10 for every non-AED, non-USD currency in
-- production (EGP EUR GBP INR JPY KES KWD MYR PKR THB; USD is pegged), from the free
-- fawazahmed0 currency-api (jsDelivr, @<date>/v1/currencies/aed.json), inverted to AED per unit
-- and rounded half-up to 8 places. That source has no file for 2025-12-10 and 2026-08-19 (the
-- day before is used). It differs from open.er-api.com (the nightly source) by ~0.3% on a
-- shared day; each row records its source. Check: INR 2026-10-03 = 0.03818088 → SIB
-- 28,400 × 0.03818088 × 1.036788 = AED 1,124.21 (billed 1,123.72).
--
-- The callers are redefined with their latest bodies (20261011000100; refresh_transaction from
-- 20261011163506), only passing the date. Every estimate is re-derived at the end.

-- ── history ─────────────────────────────────────────────────────────────────
create table private.fx_rate_history (
  currency text not null check (currency ~ '^[A-Z]{3}$'),
  as_of date not null,
  aed_per_unit numeric(18,8) not null check (aed_per_unit > 0),
  source text not null,
  updated_at timestamptz not null default now(),
  primary key (currency, as_of)
);
comment on table private.fx_rate_history is
  'Daily market FX rates (AED per 1 unit), one row per currency and day. Written by upsert_fx_rates; read by private.market_rate.';
-- `private` is unreachable for client roles; RLS without any policy and no grants keeps it so.
alter table private.fx_rate_history enable row level security;
revoke all on private.fx_rate_history from public, anon, authenticated, service_role;

insert into private.fx_rate_history (currency, as_of, aed_per_unit, source)
select currency, as_of, aed_per_unit, source from public.fx_rates
on conflict (currency, as_of) do nothing;

